/* Refactor an existing React component that fetches data in a button click handler to instead use useEffect so the data is fetched automatically when the component mounts, not on button click.<br><br><em><strong>Constraint:</strong> Only move the fetch logic; do not change the UI or styling.</em>  */


import React from 'react'

function DataFetcher() {
    const [data, setData] = useState([]);

    const handleFetch = () => {
        fetch("https://jsonplaceholder.typicode.com/posts")
            .then((response) => response.json())
            .then((result) => setData(result));
    };

    return (
        <div>
            <button onClick={handleFetch}>Fetch Data</button>

            <ul>
                {data.map((item) => (
                    <li key={item.id}>{item.title}</li>
                ))}
            </ul>
        </div>
    );
}

export default DataFetcher
